checks.command:
/bin/zsh -lc "rtk git status --short && rtk python3 -c \"import json, pathlib; paths=['evidence/current/release/rc11-manifest.json','evidence/current/release/rc11-evidence-binding.json','evidence/current/release/rc11-readiness-matrix.json']; base='6b3d7a69b37d04cbd015c63bea17a8f859e7a7cf';
for name in paths:
 d=json.loads(pathlib.Path(name).read_text()); print(name, 'keys=', sorted(d), 'source=', d.get('verified_source_commit') or d.get('source_commit'), 'target_base=',d.get('target_base_sha'), 'accepted=', 'accepted_head' in d, 'merge=', 'repository_merge_sha' in d); assert 'accepted_head' not in d and 'repository_merge_sha' not in d; assert d.get('target_base_sha') in (None,base)\""

/bin/zsh -lc "rtk python3 -c \"import hashlib, json, pathlib, subprocess; names=['CHECKPOINT_MANIFEST.json','deploy/rc11-release-identity.json','evidence/current/full-stack/verification.json','evidence/current/full-stack/source-hashes.json','evidence/current/release/CHG-33-company-qualification.json','evidence/current/release/rc11-readiness-matrix.json','evidence/current/release/rc11-manifest.json','evidence/current/release/rc11-evidence-binding.json'];
for n in names:
 p=pathlib.Path(n); print(n, p.stat().st_size, hashlib.sha256(p.read_bytes()).hexdigest())
print('branch',subprocess.check_output(['git','branch','--show-current'],text=True).strip()); print('head',subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip()); print('base_files',len(subprocess.check_output(['git','diff','--name-only','6b3d7a69b37d04cbd015c63bea17a8f859e7a7cf...HEAD'],text=True).splitlines()))\""
